#define MOD 1000000007
#define MAXN 1001

long long fact[MAXN], inv_fact[MAXN];
long long poly[MAXN], tmp[MAXN];

long long power(long long a, long long b, long long mod) {
    long long res = 1; a %= mod;
    while (b > 0) { if (b & 1) res = res * a % mod; a = a * a % mod; b >>= 1; }
    return res;
}

void precompute(int n) {
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i-1] * i % MOD;
    inv_fact[n] = power(fact[n], MOD-2, MOD);
    for (int i = n-1; i >= 0; i--) inv_fact[i] = inv_fact[i+1] * (i+1) % MOD;
}

int main() {
    int N, A, B, C, D;
    scanf("%d %d %d %d %d", &N, &A, &B, &C, &D);
    precompute(N);

    // poly represents EGF coefficients (divided by n! to store as EGF)
    // poly[n] = coefficient of x^n in EGF
    memset(poly, 0, sizeof(poly));
    poly[0] = 1;

    for (int i = A; i <= B && i <= N; i++) {
        // f_i(x) = 1 + sum_{k=C}^{D} x^(i*k) / (i!^k * k!)
        long long fi[MAXN];
        memset(fi, 0, sizeof(fi));
        fi[0] = 1; // k=0 term
        long long inv_fact_i_pow = 1; // (1/i!)^k
        long long inv_fact_i = inv_fact[i];
        for (int k = 1; k <= D && (long long)i*k <= N; k++) {
            inv_fact_i_pow = inv_fact_i_pow * inv_fact_i % MOD;
            if (k >= C) {
                int idx = i * k;
                fi[idx] = (fi[idx] + inv_fact_i_pow % MOD * inv_fact[k]) % MOD;
            }
        }
        // multiply poly by fi
        memset(tmp, 0, sizeof(tmp));
        for (int a = 0; a <= N; a++) {
            if (!poly[a]) continue;
            for (int b = 0; a+b <= N; b++) {
                if (!fi[b]) continue;
                tmp[a+b] = (tmp[a+b] + poly[a] * fi[b]) % MOD;
            }
        }
        memcpy(poly, tmp, sizeof(tmp));
    }

    long long ans = poly[N] * fact[N] % MOD;
    printf("%lld\n", ans);
    return 0;
}

