#define MOD 1000000007LL
#define MAXN 1005

static long long fact[MAXN], invfact[MAXN];
static long long dp[MAXN][MAXN];

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int N, A, B, C, D;
    if (scanf("%d %d %d %d %d", &N, &A, &B, &C, &D) != 5) return 0;

    fact[0] = 1;
    for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
    invfact[N] = modpow(fact[N], MOD - 2);
    for (int i = N; i >= 1; i--) invfact[i - 1] = invfact[i] * i % MOD;

    memset(dp, 0, sizeof(dp));
    dp[A][0] = 1;

    for (int i = A; i <= B; i++) {
        for (int j = 0; j <= N; j++) {
            if (dp[i][j] == 0) continue;

            // Use 0 groups of size i
            if (i < B) {
                dp[i + 1][j] = (dp[i + 1][j] + dp[i][j]) % MOD;
            }

            // Use k groups of size i, where C <= k <= D
            long long ways_groups = 1; // for k = 0
            long long inv_i_fact = invfact[i];
            long long inv_i_fact_pow = 1;

            for (int k = 1; k <= D; k++) {
                if (j + k * i > N) break;
                inv_i_fact_pow = inv_i_fact_pow * inv_i_fact % MOD;
                ways_groups = ways_groups * fact[j + k * i] % MOD;
                ways_groups = ways_groups * invfact[j + (k - 1) * i] % MOD;
                ways_groups = ways_groups * invfact[i] % MOD;
                ways_groups = ways_groups * invfact[k] % MOD;
                // The above recurrence is not correct to maintain cumulative value,
                // so compute directly below instead.
            }
        }

        // Recompute transitions directly and correctly
        for (int j = 0; j <= N; j++) {
            if (dp[i][j] == 0) continue;

            long long p = 1; // (i!)^{-k}
            for (int k = 1; k <= D && j + k * i <= N; k++) {
                p = p * invfact[i] % MOD;
                if (k < C) continue;

                int nj = j + k * i;
                long long add = dp[i][j];
                add = add * fact[nj] % MOD;
                add = add * invfact[j] % MOD;
                add = add * p % MOD;
                add = add * invfact[k] % MOD;

                if (i < B) dp[i + 1][nj] = (dp[i + 1][nj] + add) % MOD;
                else dp[i][nj] = (dp[i][nj] + add) % MOD;
            }
        }
    }

    printf("%lld\n", dp[B][N] % MOD);
    return 0;
}

