public class Main {
    static final long MOD = 1_000_000_007;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int A = Integer.parseInt(st.nextToken());
        int B = Integer.parseInt(st.nextToken());
        int C = Integer.parseInt(st.nextToken());
        int D = Integer.parseInt(st.nextToken());

        long[] fact = new long[N + 1];
        long[] inv_fact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i-1] * i % MOD;
        inv_fact[N] = modpow(fact[N], MOD - 2, MOD);
        for (int i = N - 1; i >= 0; i--) inv_fact[i] = inv_fact[i+1] * (i+1) % MOD;

        long[] dp = new long[N + 1];
        dp[0] = 1;

        for (int i = A; i <= B; i++) {
            long[] ndp = new long[N + 1];
            for (int j = 0; j <= N; j++) {
                if (dp[j] == 0) continue;
                // k = 0
                ndp[j] = (ndp[j] + dp[j]) % MOD;
                // k = C to D
                long coeff = 1;
                for (int k = 1; k <= D; k++) {
                    if ((long)j + (long)k * i > N) break;
                    coeff = coeff % MOD * inv_fact[i] % MOD * modpow(inv_fact[i], k-1, MOD) % MOD; // recompute
                    // Actually: coeff for k groups = inv_fact[i]^k * inv_fact[k]
                    long c = modpow(inv_fact[i], k, MOD) * inv_fact[k] % MOD;
                    if (k >= C) ndp[j + k * i] = (ndp[j + k * i] + dp[j] * c) % MOD;
                }
            }
            dp = ndp;
        }

        System.out.println(dp[N] * fact[N] % MOD);
    }

    static long modpow(long base, long exp, long mod) {
        long result = 1; base %= mod;
        while (exp > 0) { if ((exp & 1) == 1) result = result * base % mod; base = base * base % mod; exp >>= 1; }
        return result;
    }
}

