        int B = sc.nextInt();
        int C = sc.nextInt();
        int D = sc.nextInt();

        long[] dp = new long[N + 1];
        dp[0] = 1;

        // Precompute combinations C(n, k) if needed, but here we can directly multiply combinations
        long[][] comb = new long[N + 1][N + 1];
        for (int i = 0; i <= N; i++) {
            comb[i][0] = comb[i][i] = 1;
            for (int j = 1; j < i; j++) {
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
            }
        }

        for (int size = A; size <= B; size++) {
            long[] next = dp.clone();
            for (int groups = C; groups <= D && groups * size <= N; groups++) {
                // We choose groups of this size
                long ways = 1;
                int peopleLeft = N;
                // We'll iterate backwards to avoid reuse within same size
                for (int i = N; i >= 0; i--) {
                    if (dp[i] == 0) continue;
                    // try to add exactly `groups` groups of `size` to arrangement of i people
                    int totalPeople = i + groups * size;
                    if (totalPeople > N) continue;
                    long addWays = dp[i];
                    // multiply by combination: choose which people go into these new groups
                    long chooseWays = 1;
                    int remaining = N - i;
                    for (int g = 0; g < groups; g++) {
                        chooseWays = chooseWays * comb[remaining][size] % MOD;
                        remaining -= size;
                    }
                    // Divide by groups! because groups of same size are indistinguishable
                    long fact = 1;
                    for (int g = 2; g <= groups; g++) fact = fact * g % MOD;
                    chooseWays = chooseWays * modInverse(fact, MOD) % MOD;
                    next[totalPeople] = (next[totalPeople] + dp[i] * chooseWays) % MOD;
                }
            }
            dp = next;
        }

        System.out.println(dp[N] % MOD);
    }

    static long modInverse(long a, int mod) {
        return modPow(a, mod - 2, mod);
    }

    static long modPow(long a, long e, int mod) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % mod;
            a = a * a % mod;
            e >>= 1;
        }
        return res;
    }
}

