import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int A = fs.nextInt();
        int B = fs.nextInt();
        int C = fs.nextInt();
        int D = fs.nextInt();

        long[] fact = new long[N + 1];
        long[] invFact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[N] = modPow(fact[N], MOD - 2);
        for (int i = N; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;

        // dp[i][j]: using group sizes from A..i, number of ways to partition j people
        long[][] dp = new long[B + 1][N + 1];
        dp[A - 1][0] = 1;

        for (int size = A; size <= B; size++) {
            for (int used = 0; used <= N; used++) {
                // choose 0 groups of this size
                dp[size][used] = (dp[size][used] + dp[size - 1][used]) % MOD;
            }

            // precompute denominator inverse for k groups of current size:
            // 1 / ((size!)^k * k!)
            long[] waysK = new long[D + 1];
            waysK[0] = 1;
            long invSizeFact = invFact[size];
            for (int k = 1; k <= D; k++) {
                waysK[k] = waysK[k - 1] * invSizeFact % MOD * invFact[k] % MOD * fact[k - 1] % MOD;
                // Simplifies to waysK[k] = (invFact[size]^k) * invFact[k]
                // recurrence: prev * invFact[size] / k
                // implemented as prev * invFact[size] * inv(k)
                // using invFact[k] * fact[k-1] = inv(k)
            }

            for (int prevUsed = 0; prevUsed <= N; prevUsed++) {
                long base = dp[size - 1][prevUsed];
                if (base == 0) continue;

                for (int k = C; k <= D; k++) {
                    int total = prevUsed + size * k;
                    if (total > N) break;

                    // Number of ways to choose and split size*k new people into k unlabeled groups of size "size":
                    // (N - prevUsed)! / (N - total)! / (size!)^k / k!
                    long add = base;
                    add = add * fact[N - prevUsed] % MOD;
                    add = add * invFact[N - total] % MOD;
                    add = add * modPow(invFact[size], k) % MOD;
                    add = add * invFact[k] % MOD;

                    dp[size][total] = (dp[size][total] + add) % MOD;
                }
            }
        }

        System.out.println(dp[B][N] % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

