    cin >> N >> A >> B >> C >> D;

    vector<int> dp(N + 1, 0);
    dp[0] = 1;

    for (int s = A; s <= B; ++s) {
        vector<int> new_dp = dp; // case k = 0 for this size
        for (int used = 0; used <= N; ++used) {
            if (dp[used] == 0) continue;
            long long ways = dp[used];
            // try adding k groups of size s
            for (int k = C; k <= D; ++k) {
                long long add = used + k * s;
                if (add > N) break;
                // combinatorial factor: choose people for these groups, but since groups of same size are indistinguishable,
                // we just multiply ways (treat as adding groups sequentially)
                new_dp[add] = (new_dp[add] + ways) % MOD;
            }
        }
        dp = move(new_dp);
    }

    cout << dp[N] % MOD << "\n";
    return 0;
