const int MOD = 1e9 + 7;

long long power(long long a, long long b, long long mod) {
    long long res = 1; a %= mod;
    for (; b > 0; b >>= 1) { if (b & 1) res = res * a % mod; a = a * a % mod; }
    return res;
}

long long inv(long long a) { return power(a, MOD - 2, MOD); }

int main() {
    int N, A, B, C, D;
    cin >> N >> A >> B >> C >> D;

    vector<long long> fact(N + 1), inv_fact(N + 1);
    fact[0] = 1;
    for (int i = 1; i <= N; i++) fact[i] = fact[i-1] * i % MOD;
    inv_fact[N] = inv(fact[N]);
    for (int i = N-1; i >= 0; i--) inv_fact[i] = inv_fact[i+1] * (i+1) % MOD;

    vector<long long> dp(N + 1, 0);
    dp[0] = 1;

    for (int i = A; i <= B; i++) {
        vector<long long> ndp(N + 1, 0);
        for (int j = 0; j <= N; j++) {
            if (!dp[j]) continue;
            // k = 0
            ndp[j] = (ndp[j] + dp[j]) % MOD;
            // k = C to D
            long long inv_i_fact_pow = 1; // inv(i!)^k
            long long inv_k_fact = 1;
            // precompute
            long long inv_ifact = inv_fact[i]; // 1/i!
            for (int k = 1; k <= D && j + i*k <= N; k++) {
                inv_i_fact_pow = inv_i_fact_pow * inv_ifact % MOD;
                inv_k_fact = inv_k_fact * inv(k) % MOD; // 1/k!
                if (k >= C) {
                    ndp[j + i*k] = (ndp[j + i*k] + dp[j] % MOD * inv_i_fact_pow % MOD * inv_k_fact) % MOD;
                }
            }
        }
        dp = ndp;
    }

    cout << fact[N] % MOD * dp[N] % MOD << endl;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, A, B, C, D;
    cin >> N >> A >> B >> C >> D;

    vector<long long> fact(N + 1), invfact(N + 1);
    fact[0] = 1;
    for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
    invfact[N] = modpow(fact[N], MOD - 2);
    for (int i = N; i >= 1; i--) invfact[i - 1] = invfact[i] * i % MOD;

    // dp[i][j]:
    // using group sizes from A..i, number of ways to partition exactly j people
    vector<vector<long long>> dp(B + 1, vector<long long>(N + 1, 0));
    dp[A - 1][0] = 1;

    for (int i = A; i <= B; i++) {
        for (int j = 0; j <= N; j++) {
            // use 0 groups of size i
            dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD;

            // use k groups of size i, where C <= k <= D
            for (int k = C; k <= D; k++) {
                int used = i * k;
                if (used > j) break;

                // From previous j-used people, choose used people and split into k unlabeled groups of size i
                // multiplier = 1 / ((i!)^k * k!)
                long long ways = dp[i - 1][j - used];
                ways = ways * invfact[j - used] % MOD;
                ways = ways * fact[j] % MOD;
                ways = ways * modpow(invfact[i], k) % MOD;
                ways = ways * invfact[k] % MOD;

                dp[i][j] = (dp[i][j] + ways) % MOD;
            }
        }
    }

    cout << dp[B][N] % MOD << '\n';
    return 0;
}
